// frontend/orval.config.ts
// Generates the typed API client from the backend's OpenAPI document.
// OpenAPI is the source of truth: never edit files under src/api/generated by hand.
import { defineConfig } from "orval";

export default defineConfig({
  gcseCoach: {
    input: { target: "./openapi.json" },
    output: {
      target: "./src/api/generated/endpoints.ts",
      schemas: { path: "./src/api/generated/model", type: "zod" },
      client: "react-query",
      httpClient: "fetch",
      mode: "single",
      clean: true,
      formatter: "prettier",
      override: {
        mutator: { path: "./src/api/http.ts", name: "apiFetch" },
        fetch: { includeHttpResponseReturnType: false, runtimeValidation: true },
        query: { version: 5, signal: true },
        includeZodSchemaInArguments: true,
      },
    },
  },
});
